head.script:
scwin.panel2_onpanelload = function(panelId, userId) {
	if (userId == "panel3") {
		var content = document.getElementById('mf_panel2_panel_panel3_panelContent_panelContent3');
		window.ck_load = { panelId: panelId, cls: content.className, height: content.offsetHeight };
		window.ck_log1 = userId;
	}
};
scwin.panel2_onpanelunload = function(panelId, userId) {
	if (userId == "panel3") {
		var content = document.getElementById('mf_panel2_panel_panel3_panelContent_panelContent3');
		window.ck_unload = { panelId: panelId, cls: content.className, height: content.offsetHeight };
		window.ck_log2 = userId;
	}
};
scwin.checkVal1 = function() {
	return window.ck_log1 == 'panel3';
};
scwin.checkVal2 = function() {
	return window.ck_log2 == 'panel3';
};
